OUT=ROOT/'packages/campaign/chapter08_consumers/special/dynamic_roster_independent_v3';ROSTER=ROOT/'packages/campaign/roster/fixed12.m26.reference_module.json';BURN=ROOT/'packages/campaign/chapter08_consumers/boss/dragon_fire.module.v10.dynamic.json'
